import{_ as i,o as t,c as l,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"CDS Squid: RBD","description":"","frontmatter":{"title":"CDS Squid: RBD","date":"2023-07-25T00:00:00.000Z","updated":"2023-07-26T00:00:00.000Z","tags":["Ceph","RBD","Subdeveloper Planning Summit","Storage Optimization","Data Corruption"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/CDS_Squid_-_RBD.md","filePath":"posts/2023/CDS_Squid_-_RBD.md","lastUpdated":1780459816000}'),o={name:"posts/2023/CDS_Squid_-_RBD.md"};function r(n,a,s,d,u,h){return t(),l("div",null,[...a[0]||(a[0]=[e('<h3 id="会议纪要-rbd-子开发者规划峰会" tabindex="-1">会议纪要：RBD 子开发者规划峰会 <a class="header-anchor" href="#会议纪要-rbd-子开发者规划峰会" aria-label="Permalink to &quot;会议纪要：RBD 子开发者规划峰会&quot;">​</a></h3><h4 id="会议概览" tabindex="-1">会议概览 <a class="header-anchor" href="#会议概览" aria-label="Permalink to &quot;会议概览&quot;">​</a></h4><p>本次峰会主要讨论了 Ceph RBD（RADOS Block Device）的相关议题，包括镜像和快照的高优先级问题、新功能提案，以及后续行动计划。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>镜像和快照相关的高优先级问题</strong></p><ul><li><strong>数据损坏问题</strong>：在同步克隆图像时，可能存在数据损坏的风险。</li><li><strong>同步丢弃操作问题</strong>：在某些情况下，丢弃操作可能不会正确同步，导致空间未被释放。</li><li><strong>块列表错误传播问题</strong>：错误被忽略，导致从块列表恢复失败。</li><li><strong>强制提升问题</strong>：强制提升操作可能需要无限期等待同步完成。</li></ul></li><li><p><strong>新功能提案</strong></p><ul><li><strong>快照镜像的一致性组</strong>：讨论了快照镜像的一致性组功能。</li><li><strong>性能改进</strong>：包括从快照克隆、流式快照增量等提案，旨在提高镜像同步的性能和效率。</li></ul></li><li><p><strong>其他非镜像相关议题</strong></p><ul><li><strong>迁移功能改进</strong>：包括从非Ceph源进行实时迁移的支持，以及与原生加密交互的改进。</li><li><strong>Windows支持改进</strong>：讨论了Windows NBD驱动和守护进程的改进，以支持持久保留和多路复用。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了高优先级问题的修复计划，特别是数据损坏和同步丢弃操作的问题。</li><li>对于新功能提案，如快照镜像的一致性组和性能改进，将进行进一步的讨论和评估。</li><li>对于非镜像相关议题，如迁移功能和Windows支持，将逐步推进相关改进。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续修复高优先级问题，并确保数据完整性和同步的可靠性。</li><li>对新功能提案进行详细讨论，评估其实现的可行性和优先级。</li><li>推进迁移功能和Windows支持的改进，确保功能的稳定性和性能。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议记录将被保存，供后续参考和审查。</li><li>鼓励与会者提出未在列表中的议题，以便在后续会议中讨论。</li></ul><p>会议结束时，主持人感谢所有参与者的参与，并期待在后续的沟通渠道中继续讨论和合作。</p>',12)])])}const c=i(o,[["render",r]]);export{_ as __pageData,c as default};
